/* ============================================================
   Standalone storage — replaces Claude's built-in artifact storage
   with a real Supabase table, so the app works as an independent
   site with no dependency on claude.ai. Every read/write in this
   file goes through window.storage.get/set/delete (the same shape
   Claude's storage used), so nothing else in the file needed to
   change — this shim is the only new piece.
   See README.md for the one-time Supabase table setup (SQL included).
   ============================================================ */
const supabase = createClient(
  import.meta.env.VITE_SUPABASE_URL,
  import.meta.env.VITE_SUPABASE_ANON_KEY
);

window.storage = {
  async get(key) {
    const { data, error } = await supabase
      .from("app_storage")
      .select("value")
      .eq("key", key)
      .maybeSingle();
    if (error) throw error;
    return data ? { key, value: data.value } : null;
  },
  async set(key, value) {
    const { error } = await supabase
      .from("app_storage")
      .upsert({ key, value, updated_at: new Date().toISOString() });
    if (error) throw error;
    return { key, value };
  },
  async delete(key) {
    const { error } = await supabase.from("app_storage").delete().eq("key", key);
    if (error) return null;
    return { key, deleted: true };
  },
};

